content.query:
let UPN = "{UserPrincipalName}";
let Operation_ = "{Operation}";
OfficeActivity
| where UserId =~ UPN
| where "{Operation:lable}"=="All" or Operation in ({Operation})
| project TimeGenerated, UserAgent, Operation, OfficeWorkload, ClientIP, Site_Url, SourceRelativeUrl, SourceFileName

let UserPrincipalName_ = "{UserPrincipalName}";
SecurityIncident
| extend SystemAlertId = tostring(AlertIds[0])
| extend AssignedTo_ = tostring(Owner.assignedTo)
| summarize arg_max(TimeGenerated, *) by IncidentNumber
| join SecurityAlert on SystemAlertId
//| extend EntityName = tostring(parse_json(Entities)[1].DisplayName)
//| where EntityName contains UserPrincipalName_
| where Entities contains UserPrincipalName_
| project TimeGenerated,IncidentNumber,Severity, Title, Description,AssignedTo_, Entities, IncidentUrl
